/**
 * A message an inbox received, or the trace of one it refused.
 */
export type MessageWritable = {
    /**
     * The real attachments of the message, kept or not, by name then identifier; an embedded image is not one (see `inlines`). Absent on a refused message. Download a kept one with `downloadAttachment`, by its identifier: the response never says where the bytes are.
     */
    attachments?: Array<{
        /**
         * `sha256:` then the sha256 of the decoded bytes, in hexadecimal.
         */
        checksum: string | null;
        /**
         * The type the sender declared, which nothing checked against the bytes.
         */
        contentType: string | null;
        /**
         * As the sender wrote it: data, never a path.
         */
        fileName: string;
        id: string;
        /**
         * Why the bytes were not kept; only on an attachment that was not.
         */
        reason?: 'PERFORMANCE_MODE' | 'TRIAL_INBOX' | 'ATTACHMENT_TOO_LARGE' | 'STORAGE_QUOTA_EXCEEDED';
        /**
         * Of the decoded bytes.
         */
        sizeBytes: number;
        /**
         * Whether the bytes were kept, so whether there is something to download. It is `reason` being absent.
         */
        stored: boolean;
    }>;
    /**
     * Every code the ingester found, the best candidate first. Absent on a refused message.
     */
    codes?: Array<string>;
    /**
     * What the connection knew, in the read of one message and in a search of the public API: null when the ingester knew nothing, and each fact null when it did not know it, never an empty string. A refused message keeps it.
     */
    connection?: {
        helo: string | null;
        remoteIp: string | null;
        tlsCipher: string | null;
        /**
         * Named, such as `TLS 1.3`, never a number.
         */
        tlsVersion: string | null;
    } | null;
    /**
     * Why the message was refused; only on a `quota_exceeded` message, which carries nothing derived. One of PLAN_QUOTA_EXCEEDED, INBOX_QUOTA_EXCEEDED, WORKSPACE_QUOTA_EXCEEDED, OVERAGE_CAP_REACHED, DAILY_SPIKE_CAP, SUBSCRIPTION_SUSPENDED; a code a later version of the ingester writes is said as it is.
     */
    errorCode?: string;
    /**
     * The values the extractors of the inbox found, by key. Absent on a refused message.
     */
    extract?: {
        [key: string]: string;
    };
    /**
     * The display name of the sender, when the message gave one. Absent on a refused message.
     */
    fromName?: string | null;
    /**
     * The headers of the message, names in lower case; in the read of one message and in a search of the public API. Absent on a refused message.
     */
    headers?: {
        [key: string]: string;
    };
    /**
     * In the read of one message and in a search of the public API; absent from the list of an inbox and from the search of `app`. Absent on a refused message.
     */
    htmlBody?: string | null;
    /**
     * The images embedded in the body, such as a signature logo: the parts the message declared `inline`. They are not attachments (never counted among them, never found by a search) and carry no link. Absent on a refused message.
     */
    inlines?: Array<{
        /**
         * What the `cid:` of the HTML body names.
         */
        contentId: string | null;
        contentType: string | null;
        fileName: string;
        id: string;
        sizeBytes: number;
    }>;
    /**
     * The links of the message, in order of appearance, the HTML part first. Absent on a refused message.
     */
    links?: Array<string>;
    /**
     * The one-time code the ingester extracted, null when there is none. Absent on a refused message.
     */
    otp?: string | null;
    /**
     * The state of the message: `parsed`, everything derived from the body is filled in, or `quota_exceeded`, refused and nothing derived. Read it before anything derived from the body.
     */
    status?: 'parsed' | 'quota_exceeded';
    /**
     * Absent on a refused message; null when there is none.
     */
    subject?: string | null;
    /**
     * In the read of one message and in a search of the public API; absent from the list of an inbox and from the search of `app`. Absent on a refused message.
     */
    textBody?: string | null;
};

